@Test
public void testKeyPrefixFilter() throws IOException {
    List<Map.Entry<byte[], byte[]>> result = null;
    RuntimeException exception = null;
    try {
        new KeyPrefixFilter().addFilter("b0", true).addFilter("b");
    } catch (IllegalArgumentException e) {
        exception = e;
    }
    assertTrue(exception.getMessage().contains("KeyPrefix: b already " + "rejected"));
    try {
        new KeyPrefixFilter().addFilter("b0").addFilter("b", true);
    } catch (IllegalArgumentException e) {
        exception = e;
    }
    assertTrue(exception.getMessage().contains("KeyPrefix: b already " + "accepted"));
    try {
        new KeyPrefixFilter().addFilter("b", true).addFilter("b0");
    } catch (IllegalArgumentException e) {
        exception = e;
    }
    assertTrue(exception.getMessage().contains("KeyPrefix: b0 already " + "rejected"));
    try {
        new KeyPrefixFilter().addFilter("b").addFilter("b0", true);
    } catch (IllegalArgumentException e) {
        exception = e;
    }
    assertTrue(exception.getMessage().contains("KeyPrefix: b0 already " + "accepted"));
    MetadataKeyFilter filter1 = new KeyPrefixFilter(true).addFilter("a0").addFilter("a1").addFilter("b", true);
    result = store.getRangeKVs(null, 100, filter1);
    assertEquals(2, result.size());
    assertTrue(result.stream().anyMatch(entry -> new String(entry.getKey()).startsWith("a0")) && result.stream().anyMatch(entry -> new String(entry.getKey()).startsWith("a1")));
    filter1 = new KeyPrefixFilter(true).addFilter("b", true);
    result = store.getRangeKVs(null, 100, filter1);
    assertEquals(0, result.size());
    filter1 = new KeyPrefixFilter().addFilter("b", true);
    result = store.getRangeKVs(null, 100, filter1);
    assertEquals(10, result.size());
    assertTrue(result.stream().allMatch(entry -> new String(entry.getKey()).startsWith("a")));
}

