    cmdStatusMap.put(obj2.getCmdId(), obj2);
    Assert.assertEquals("Should publish report with 2 status objects", 2, ((CommandStatusReportPublisher) publisher).getReport().getCmdStatusCount());
    Assert.assertEquals("Next report should have 1 status objects as command status o" + "bjects are still in Pending state", 1, ((CommandStatusReportPublisher) publisher).getReport().getCmdStatusCount());
    Assert.assertTrue("Next report should have 1 status objects as command status " + "objects are still in Pending state", ((CommandStatusReportPublisher) publisher).getReport().getCmdStatusList().get(0).getStatus().equals(Status.PENDING));
    executorService.shutdown();
}

