@Test
public void testInprogressFilter() throws InterruptedException {
    EventQueue queue = new EventQueue();
    EventWatcher<UnderreplicatedEvent, ReplicationCompletedEvent> replicationWatcher = createEventWatcher();
    EventHandlerStub<UnderreplicatedEvent> underReplicatedEvents = new EventHandlerStub<>();
