    for (DatanodeDetails datanode : datanodes) {
        selectedCount.put(datanode, 0);
    }
    for (int i = 0; i < 1000; i++) {
        //when
        List<DatanodeDetails> datanodeDetails = scmContainerPlacementRandom.chooseDatanodes(existingNodes, 1, 15);
