            protected List<DatanodeDetails> getCurrentReplicas(ReplicationRequest request) throws IOException {
                return listOfDatanodeDetails.subList(0, 2);
            }
        };
        replicationManager.start();
        queue.fireEvent(SCMEvents.REPLICATE_CONTAINER, new ReplicationRequest(1l, (short) 2, System.currentTimeMillis(), (short) 3));
        Thread.sleep(500L);
        queue.processAll(1000L);
        Assert.assertEquals(1, trackReplicationEvents.size());
        Assert.assertEquals(1, copyEvents.size());
        Assert.assertEquals(trackReplicationEvents.get(0).getId(), copyEvents.get(0).getCommand().getId());
        //event is timed out
        Thread.sleep(1500);
        queue.processAll(1000L);
        //original copy command + retry
        Assert.assertEquals(2, trackReplicationEvents.size());
        Assert.assertEquals(2, copyEvents.size());
    } finally {
        if (leaseManager != null) {
            leaseManager.shutdown();
        }
    }
}

