@Test
public void testCloseContainerEventWithValidContainers() throws IOException {
    GenericTestUtils.LogCapturer logCapturer = GenericTestUtils.LogCapturer.captureLogs(CloseContainerEventHandler.LOG);
    ContainerWithPipeline containerWithPipeline = mapping.allocateContainer(HddsProtos.ReplicationType.STAND_ALONE, HddsProtos.ReplicationFactor.ONE, "ozone");
    ContainerID id = new ContainerID(containerWithPipeline.getContainerInfo().getContainerID());
    DatanodeDetails datanode = containerWithPipeline.getPipeline().getLeader();
    int closeCount = nodeManager.getCommandCount(datanode);
    eventQueue.fireEvent(CLOSE_CONTAINER, id);
    eventQueue.processAll(1000);
    // At this point of time, the allocated container is not in open
    // state, so firing close container event should not queue CLOSE
    // command in the Datanode
    Assert.assertEquals(0, nodeManager.getCommandCount(datanode));
    //Execute these state transitions so that we can close the container.
    mapping.updateContainerState(id.getId(), CREATED);
    eventQueue.fireEvent(CLOSE_CONTAINER, new ContainerID(containerWithPipeline.getContainerInfo().getContainerID()));
    eventQueue.processAll(1000);
    Assert.assertEquals(closeCount + 1, nodeManager.getCommandCount(datanode));
    Assert.assertEquals(HddsProtos.LifeCycleState.CLOSING, mapping.getStateManager().getContainer(id).getState());
}

@Test
public void testCloseContainerEventWithRatis() throws IOException {
    GenericTestUtils.LogCapturer logCapturer = GenericTestUtils.LogCapturer.captureLogs(CloseContainerEventHandler.LOG);
    ContainerWithPipeline containerWithPipeline = mapping.allocateContainer(HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.THREE, "ozone");
    ContainerID id = new ContainerID(containerWithPipeline.getContainerInfo().getContainerID());
    int[] closeCount = new int[3];
    eventQueue.fireEvent(CLOSE_CONTAINER, id);
    eventQueue.processAll(1000);
    int i = 0;
    for (DatanodeDetails details : containerWithPipeline.getPipeline().getMachines()) {
        closeCount[i] = nodeManager.getCommandCount(details);
        i++;
    }
    i = 0;
    for (DatanodeDetails details : containerWithPipeline.getPipeline().getMachines()) {
        Assert.assertEquals(closeCount[i], nodeManager.getCommandCount(details));
        i++;
    }
    //Execute these state transitions so that we can close the container.
    mapping.updateContainerState(id.getId(), CREATED);
    eventQueue.fireEvent(CLOSE_CONTAINER, id);
    eventQueue.processAll(1000);
    i = 0;
    // Make sure close is queued for each datanode on the pipeline
    for (DatanodeDetails details : containerWithPipeline.getPipeline().getMachines()) {
        Assert.assertEquals(closeCount[i] + 1, nodeManager.getCommandCount(details));
        Assert.assertEquals(HddsProtos.LifeCycleState.CLOSING, mapping.getStateManager().getContainer(id).getState());
        i++;
    }
}

