@Test
public void testUpdateContainerState() throws IOException {
    NavigableSet<ContainerID> containerList = containerStateManager.getMatchingContainerIDs(containerOwner, xceiverClientManager.getType(), xceiverClientManager.getFactor(), HddsProtos.LifeCycleState.ALLOCATED);
    int containers = containerList == null ? 0 : containerList.size();
    Assert.assertEquals(0, containers);
    // Allocate container1 and update its state from ALLOCATED -> CREATING ->
    // OPEN -> CLOSING -> CLOSED -> DELETING -> DELETED
    ContainerWithPipeline container1 = scm.getClientProtocolServer().allocateContainer(xceiverClientManager.getType(), xceiverClientManager.getFactor(), containerOwner);
    containers = containerStateManager.getMatchingContainerIDs(containerOwner, xceiverClientManager.getType(), xceiverClientManager.getFactor(), HddsProtos.LifeCycleState.ALLOCATED).size();
    Assert.assertEquals(1, containers);
    scmContainerMapping.updateContainerState(container1.getContainerInfo().getContainerID(), HddsProtos.LifeCycleEvent.CREATE);
    containers = containerStateManager.getMatchingContainerIDs(containerOwner, xceiverClientManager.getType(), xceiverClientManager.getFactor(), HddsProtos.LifeCycleState.CREATING).size();
    Assert.assertEquals(1, containers);
    scmContainerMapping.updateContainerState(container1.getContainerInfo().getContainerID(), HddsProtos.LifeCycleEvent.CREATED);
    containers = containerStateManager.getMatchingContainerIDs(containerOwner, xceiverClientManager.getType(), xceiverClientManager.getFactor(), HddsProtos.LifeCycleState.OPEN).size();
    Assert.assertEquals(1, containers);
    scmContainerMapping.updateContainerState(container1.getContainerInfo().getContainerID(), HddsProtos.LifeCycleEvent.FINALIZE);
    containers = containerStateManager.getMatchingContainerIDs(containerOwner, xceiverClientManager.getType(), xceiverClientManager.getFactor(), HddsProtos.LifeCycleState.CLOSING).size();
    Assert.assertEquals(1, containers);
    scmContainerMapping.updateContainerState(container1.getContainerInfo().getContainerID(), HddsProtos.LifeCycleEvent.CLOSE);
    containers = containerStateManager.getMatchingContainerIDs(containerOwner, xceiverClientManager.getType(), xceiverClientManager.getFactor(), HddsProtos.LifeCycleState.CLOSED).size();
    Assert.assertEquals(1, containers);
    scmContainerMapping.updateContainerState(container1.getContainerInfo().getContainerID(), HddsProtos.LifeCycleEvent.DELETE);
    containers = containerStateManager.getMatchingContainerIDs(containerOwner, xceiverClientManager.getType(), xceiverClientManager.getFactor(), HddsProtos.LifeCycleState.DELETING).size();
    Assert.assertEquals(1, containers);
    scmContainerMapping.updateContainerState(container1.getContainerInfo().getContainerID(), HddsProtos.LifeCycleEvent.CLEANUP);
    containers = containerStateManager.getMatchingContainerIDs(containerOwner, xceiverClientManager.getType(), xceiverClientManager.getFactor(), HddsProtos.LifeCycleState.DELETED).size();
    Assert.assertEquals(1, containers);
    // Allocate container1 and update its state from ALLOCATED -> CREATING ->
    // DELETING
    ContainerWithPipeline container2 = scm.getClientProtocolServer().allocateContainer(xceiverClientManager.getType(), xceiverClientManager.getFactor(), containerOwner);
    scmContainerMapping.updateContainerState(container2.getContainerInfo().getContainerID(), HddsProtos.LifeCycleEvent.CREATE);
    scmContainerMapping.updateContainerState(container2.getContainerInfo().getContainerID(), HddsProtos.LifeCycleEvent.TIMEOUT);
    containers = containerStateManager.getMatchingContainerIDs(containerOwner, xceiverClientManager.getType(), xceiverClientManager.getFactor(), HddsProtos.LifeCycleState.DELETING).size();
    Assert.assertEquals(1, containers);
    // Allocate container1 and update its state from ALLOCATED -> CREATING ->
    // OPEN -> CLOSING -> CLOSED
    ContainerWithPipeline container3 = scm.getClientProtocolServer().allocateContainer(xceiverClientManager.getType(), xceiverClientManager.getFactor(), containerOwner);
    scmContainerMapping.updateContainerState(container3.getContainerInfo().getContainerID(), HddsProtos.LifeCycleEvent.CREATE);
    scmContainerMapping.updateContainerState(container3.getContainerInfo().getContainerID(), HddsProtos.LifeCycleEvent.CREATED);
    scmContainerMapping.updateContainerState(container3.getContainerInfo().getContainerID(), HddsProtos.LifeCycleEvent.FINALIZE);
    scmContainerMapping.updateContainerState(container3.getContainerInfo().getContainerID(), HddsProtos.LifeCycleEvent.CLOSE);
    containers = containerStateManager.getMatchingContainerIDs(containerOwner, xceiverClientManager.getType(), xceiverClientManager.getFactor(), HddsProtos.LifeCycleState.CLOSED).size();
    Assert.assertEquals(1, containers);
}

@Test
public void testUpdatingAllocatedBytes() throws Exception {
    ContainerWithPipeline container1 = scm.getClientProtocolServer().allocateContainer(xceiverClientManager.getType(), xceiverClientManager.getFactor(), containerOwner);
    scmContainerMapping.updateContainerState(container1.getContainerInfo().getContainerID(), HddsProtos.LifeCycleEvent.CREATE);
    scmContainerMapping.updateContainerState(container1.getContainerInfo().getContainerID(), HddsProtos.LifeCycleEvent.CREATED);
    Random ran = new Random();
    long allocatedSize = 0;
    for (int i = 0; i < 5; i++) {
        long size = Math.abs(ran.nextLong() % OzoneConsts.GB);
        allocatedSize += size;
        // trigger allocating bytes by calling getMatchingContainer
        ContainerInfo info = containerStateManager.getMatchingContainer(size, containerOwner, xceiverClientManager.getType(), xceiverClientManager.getFactor(), HddsProtos.LifeCycleState.OPEN);
        Assert.assertEquals(container1.getContainerInfo().getContainerID(), info.getContainerID());
        ContainerMapping containerMapping = (ContainerMapping) scmContainerMapping;
        // manually trigger a flush, this will persist the allocated bytes value
        // to disk
        containerMapping.flushContainerInfo();
        // the persisted value should always be equal to allocated size.
        byte[] containerBytes = containerMapping.getContainerStore().get(Longs.toByteArray(container1.getContainerInfo().getContainerID()));
        HddsProtos.SCMContainerInfo infoProto = HddsProtos.SCMContainerInfo.PARSER.parseFrom(containerBytes);
        ContainerInfo currentInfo = ContainerInfo.fromProtobuf(infoProto);
        Assert.assertEquals(allocatedSize, currentInfo.getAllocatedBytes());
    }
}

@Test
public void testReplicaMap() throws Exception {
    GenericTestUtils.setLogLevel(ContainerStateMap.getLOG(), Level.DEBUG);
    GenericTestUtils.LogCapturer logCapturer = GenericTestUtils.LogCapturer.captureLogs(ContainerStateMap.getLOG());
    DatanodeDetails dn1 = DatanodeDetails.newBuilder().setHostName("host1").setIpAddress("1.1.1.1").setUuid(UUID.randomUUID().toString()).build();
    DatanodeDetails dn2 = DatanodeDetails.newBuilder().setHostName("host2").setIpAddress("2.2.2.2").setUuid(UUID.randomUUID().toString()).build();
    // Test 1: no replica's exist
    ContainerID containerID = ContainerID.valueof(RandomUtils.nextLong());
    Set<DatanodeDetails> replicaSet;
    LambdaTestUtils.intercept(SCMException.class, "", () -> {
        containerStateManager.getContainerReplicas(containerID);
    });
    // Test 2: Add replica nodes and then test
    containerStateManager.addContainerReplica(containerID, dn1);
    containerStateManager.addContainerReplica(containerID, dn2);
    replicaSet = containerStateManager.getContainerReplicas(containerID);
    Assert.assertEquals(2, replicaSet.size());
    Assert.assertTrue(replicaSet.contains(dn1));
    Assert.assertTrue(replicaSet.contains(dn2));
    // Test 3: Remove one replica node and then test
    containerStateManager.removeContainerReplica(containerID, dn1);
    replicaSet = containerStateManager.getContainerReplicas(containerID);
    Assert.assertEquals(1, replicaSet.size());
    Assert.assertFalse(replicaSet.contains(dn1));
    Assert.assertTrue(replicaSet.contains(dn2));
    // Test 3: Remove second replica node and then test
    containerStateManager.removeContainerReplica(containerID, dn2);
    replicaSet = containerStateManager.getContainerReplicas(containerID);
    Assert.assertEquals(0, replicaSet.size());
    Assert.assertFalse(replicaSet.contains(dn1));
    Assert.assertFalse(replicaSet.contains(dn2));
    // Test 4: Re-insert dn1
    containerStateManager.addContainerReplica(containerID, dn1);
    replicaSet = containerStateManager.getContainerReplicas(containerID);
    Assert.assertEquals(1, replicaSet.size());
    Assert.assertTrue(replicaSet.contains(dn1));
    Assert.assertFalse(replicaSet.contains(dn2));
    // Re-insert dn2
    containerStateManager.addContainerReplica(containerID, dn2);
    replicaSet = containerStateManager.getContainerReplicas(containerID);
    Assert.assertEquals(2, replicaSet.size());
    Assert.assertTrue(replicaSet.contains(dn1));
    Assert.assertTrue(replicaSet.contains(dn2));
    Assert.assertFalse(logCapturer.getOutput().contains("ReplicaMap already contains entry for container Id: " + containerID.toString() + ",DataNode: " + dn1.toString()));
    // Re-insert dn1
    containerStateManager.addContainerReplica(containerID, dn1);
    replicaSet = containerStateManager.getContainerReplicas(containerID);
    Assert.assertEquals(2, replicaSet.size());
    Assert.assertTrue(replicaSet.contains(dn1));
    Assert.assertTrue(replicaSet.contains(dn2));
    Assert.assertTrue(logCapturer.getOutput().contains("ReplicaMap already contains entry for container Id: " + containerID.toString() + ",DataNode: " + dn1.toString()));
}

