        cluster.getStorageContainerManager().getScmNodeManager().addDatanodeCommand(details.getUuid(), new CloseContainerCommand(containerID, HddsProtos.ReplicationType.RATIS, pipeline.getId()));
    }
    for (DatanodeDetails datanodeDetails : datanodes) {
        GenericTestUtils.waitFor(() -> isContainerClosed(cluster, containerID, datanodeDetails), 500, 15 * 1000);
        //double check if it's really closed (waitFor also throws an exception)
