    }
    Assert.assertFalse(logCapturer.getOutput().contains("submitting CloseContainer request over STAND_ALONE " + "server for container " + containerID));
    // Make sure it was really closed via StandAlone not Ratis server
    Assert.assertTrue((logCapturer.getOutput().contains("submitting CloseContainer request over RATIS server for container " + containerID)));
}

