@Test
public void testBlockDeletion() throws Exception {
    Configuration conf = new OzoneConfiguration();
    conf.set(ScmConfigKeys.OZONE_SCM_KEY_VALUE_CONTAINER_DELETION_CHOOSING_POLICY, RandomContainerDeletionChoosingPolicy.class.getName());
    conf.setInt(OZONE_BLOCK_DELETING_CONTAINER_LIMIT_PER_INTERVAL, 10);
    conf.setInt(OZONE_BLOCK_DELETING_LIMIT_PER_CONTAINER, 2);
    ContainerSet containerSet = new ContainerSet();
    createToDeleteBlocks(containerSet, conf, 1, 3, 1);
    BlockDeletingServiceTestImpl svc = new BlockDeletingServiceTestImpl(containerSet, 1000, conf);
    svc.start();
    GenericTestUtils.waitFor(() -> svc.isStarted(), 100, 3000);
    // Ensure 1 container was created
    List<ContainerData> containerData = Lists.newArrayList();
    containerSet.listContainer(0L, 1, containerData);
    Assert.assertEquals(1, containerData.size());
    MetadataStore meta = KeyUtils.getDB((KeyValueContainerData) containerData.get(0), conf);
    Map<Long, Container> containerMap = containerSet.getContainerMap();
    long transactionId = containerMap.get(containerData.get(0).getContainerID()).getContainerData().getDeleteTransactionId();
    // Number of deleted blocks in container should be equal to 0 before
    // block delete
    Assert.assertEquals(0, transactionId);
    // Ensure there are 3 blocks under deletion and 0 deleted blocks
    Assert.assertEquals(3, getUnderDeletionBlocksCount(meta));
    Assert.assertEquals(0, getDeletedBlocksCount(meta));
    // An interval will delete 1 * 2 blocks
    deleteAndWait(svc, 1);
    Assert.assertEquals(1, getUnderDeletionBlocksCount(meta));
    Assert.assertEquals(2, getDeletedBlocksCount(meta));
    deleteAndWait(svc, 2);
    Assert.assertEquals(0, getUnderDeletionBlocksCount(meta));
    Assert.assertEquals(3, getDeletedBlocksCount(meta));
    deleteAndWait(svc, 3);
    Assert.assertEquals(0, getUnderDeletionBlocksCount(meta));
    Assert.assertEquals(3, getDeletedBlocksCount(meta));
    svc.shutdown();
}

