@Test
public void testCloseContainer() throws Exception {
    MiniOzoneCluster cluster = null;
    XceiverClient client = null;
    ContainerProtos.ContainerCommandResponseProto response;
    ContainerProtos.ContainerCommandRequestProto writeChunkRequest, putKeyRequest, request;
    try {
        OzoneConfiguration conf = newOzoneConfiguration();
        client = createClientForTesting(conf);
        cluster = MiniOzoneCluster.newBuilder(conf).setRandomContainerPort(false).build();
        cluster.waitForClusterToBeReady();
        client.connect();
        long containerID = ContainerTestHelper.getTestContainerID();
        createContainerForTesting(client, containerID);
        writeChunkRequest = writeChunkForContainer(client, containerID, 1024);
        putKeyRequest = ContainerTestHelper.getPutKeyRequest(client.getPipeline(), writeChunkRequest.getWriteChunk());
        // Put key before closing.
        response = client.sendCommand(putKeyRequest);
        Assert.assertNotNull(response);
        Assert.assertEquals(ContainerProtos.Result.SUCCESS, response.getResult());
        Assert.assertTrue(putKeyRequest.getTraceID().equals(response.getTraceID()));
        // Close the contianer.
        request = ContainerTestHelper.getCloseContainer(client.getPipeline(), containerID);
        response = client.sendCommand(request);
        Assert.assertNotNull(response);
        Assert.assertEquals(ContainerProtos.Result.SUCCESS, response.getResult());
        Assert.assertTrue(request.getTraceID().equals(response.getTraceID()));
        // Assert that none of the write  operations are working after close.
        // Write chunks should fail now.
        response = client.sendCommand(writeChunkRequest);
        Assert.assertNotNull(response);
        Assert.assertEquals(ContainerProtos.Result.CLOSED_CONTAINER_IO, response.getResult());
        Assert.assertTrue(writeChunkRequest.getTraceID().equals(response.getTraceID()));
        // Read chunk must work on a closed container.
        request = ContainerTestHelper.getReadChunkRequest(client.getPipeline(), writeChunkRequest.getWriteChunk());
        response = client.sendCommand(request);
        Assert.assertNotNull(response);
        Assert.assertEquals(ContainerProtos.Result.SUCCESS, response.getResult());
        Assert.assertTrue(request.getTraceID().equals(response.getTraceID()));
        // Put key will fail on a closed container.
        response = client.sendCommand(putKeyRequest);
        Assert.assertNotNull(response);
        Assert.assertEquals(ContainerProtos.Result.CLOSED_CONTAINER_IO, response.getResult());
        Assert.assertTrue(putKeyRequest.getTraceID().equals(response.getTraceID()));
        // Get key must work on the closed container.
        request = ContainerTestHelper.getKeyRequest(client.getPipeline(), putKeyRequest.getPutKey());
        response = client.sendCommand(request);
        int chunksCount = putKeyRequest.getPutKey().getKeyData().getChunksCount();
        ContainerTestHelper.verifyGetKey(request, response, chunksCount);
        // Delete Key must fail on a closed container.
        request = ContainerTestHelper.getDeleteKeyRequest(client.getPipeline(), putKeyRequest.getPutKey());
        response = client.sendCommand(request);
        Assert.assertNotNull(response);
        Assert.assertEquals(ContainerProtos.Result.CLOSED_CONTAINER_IO, response.getResult());
        Assert.assertTrue(request.getTraceID().equals(response.getTraceID()));
    } finally {
        if (client != null) {
            client.close();
        }
        if (cluster != null) {
            cluster.shutdown();
        }
    }
}

@Test
public void testDeleteContainer() throws Exception {
    MiniOzoneCluster cluster = null;
    XceiverClient client = null;
    ContainerProtos.ContainerCommandResponseProto response;
    ContainerProtos.ContainerCommandRequestProto request, writeChunkRequest, putKeyRequest;
    try {
        OzoneConfiguration conf = newOzoneConfiguration();
        client = createClientForTesting(conf);
        cluster = MiniOzoneCluster.newBuilder(conf).setRandomContainerPort(false).build();
        cluster.waitForClusterToBeReady();
        client.connect();
        long containerID = ContainerTestHelper.getTestContainerID();
        createContainerForTesting(client, containerID);
        writeChunkRequest = writeChunkForContainer(client, containerID, 1024);
        putKeyRequest = ContainerTestHelper.getPutKeyRequest(client.getPipeline(), writeChunkRequest.getWriteChunk());
        // Put key before deleting.
        response = client.sendCommand(putKeyRequest);
        Assert.assertNotNull(response);
        Assert.assertEquals(ContainerProtos.Result.SUCCESS, response.getResult());
        Assert.assertTrue(putKeyRequest.getTraceID().equals(response.getTraceID()));
        // Container cannot be deleted forcibly because
        // the container is not closed.
        request = ContainerTestHelper.getDeleteContainer(client.getPipeline(), containerID, true);
        response = client.sendCommand(request);
        Assert.assertNotNull(response);
        Assert.assertEquals(ContainerProtos.Result.DELETE_ON_OPEN_CONTAINER, response.getResult());
        Assert.assertTrue(request.getTraceID().equals(response.getTraceID()));
        // Close the container.
        request = ContainerTestHelper.getCloseContainer(client.getPipeline(), containerID);
        response = client.sendCommand(request);
        Assert.assertNotNull(response);
        Assert.assertEquals(ContainerProtos.Result.SUCCESS, response.getResult());
        Assert.assertTrue(request.getTraceID().equals(response.getTraceID()));
        // Container cannot be deleted because the container is not empty.
        request = ContainerTestHelper.getDeleteContainer(client.getPipeline(), containerID, false);
        response = client.sendCommand(request);
        Assert.assertNotNull(response);
        Assert.assertEquals(ContainerProtos.Result.ERROR_CONTAINER_NOT_EMPTY, response.getResult());
        Assert.assertTrue(request.getTraceID().equals(response.getTraceID()));
        // Container can be deleted forcibly because
        // it is closed and non-empty.
        request = ContainerTestHelper.getDeleteContainer(client.getPipeline(), containerID, true);
        response = client.sendCommand(request);
        Assert.assertNotNull(response);
        Assert.assertEquals(ContainerProtos.Result.SUCCESS, response.getResult());
        Assert.assertTrue(request.getTraceID().equals(response.getTraceID()));
    } finally {
        if (client != null) {
            client.close();
        }
        if (cluster != null) {
            cluster.shutdown();
        }
    }
}

