@Test
public void testGetServiceList() throws Exception {
    OzoneManagerHttpServer server = cluster.getOzoneManager().getHttpServer();
    HttpClient client = HttpClients.createDefault();
    String connectionUri = "http://" + NetUtils.getHostPortString(server.getHttpAddress());
    HttpGet httpGet = new HttpGet(connectionUri + "/serviceList");
    HttpResponse response = client.execute(httpGet);
    String serviceListJson = EntityUtils.toString(response.getEntity());
    ObjectMapper objectMapper = new ObjectMapper();
    TypeReference<List<ServiceInfo>> serviceInfoReference = new TypeReference<List<ServiceInfo>>() {
    };
    List<ServiceInfo> serviceInfos = objectMapper.readValue(serviceListJson, serviceInfoReference);
    Map<HddsProtos.NodeType, ServiceInfo> serviceMap = new HashMap<>();
    for (ServiceInfo serviceInfo : serviceInfos) {
        serviceMap.put(serviceInfo.getNodeType(), serviceInfo);
    }
    InetSocketAddress omAddress = getOmAddressForClients(conf);
    ServiceInfo omInfo = serviceMap.get(HddsProtos.NodeType.OM);
    Assert.assertEquals(omAddress.getHostName(), omInfo.getHostname());
    Assert.assertEquals(omAddress.getPort(), omInfo.getPort(ServicePort.Type.RPC));
    Assert.assertEquals(server.getHttpAddress().getPort(), omInfo.getPort(ServicePort.Type.HTTP));
    InetSocketAddress scmAddress = getScmAddressForClients(conf);
    ServiceInfo scmInfo = serviceMap.get(HddsProtos.NodeType.SCM);
    Assert.assertEquals(scmAddress.getHostName(), scmInfo.getHostname());
    Assert.assertEquals(scmAddress.getPort(), scmInfo.getPort(ServicePort.Type.RPC));
    ServiceInfo datanodeInfo = serviceMap.get(HddsProtos.NodeType.DATANODE);
    DatanodeDetails datanodeDetails = cluster.getHddsDatanodes().get(0).getDatanodeDetails();
    Assert.assertEquals(datanodeDetails.getHostName(), datanodeInfo.getHostname());
    Map<ServicePort.Type, Integer> ports = datanodeInfo.getPorts();
    for (ServicePort.Type type : ports.keySet()) {
        switch(type) {
            case HTTP:
            case HTTPS:
                Assert.assertEquals(datanodeDetails.getPort(DatanodeDetails.Port.Name.REST).getValue(), ports.get(type));
                break;
            default:
                // OM only sends Datanode's info port details
                // i.e. HTTP or HTTPS
                // Other ports are not expected as of now.
                Assert.fail();
                break;
        }
    }
}

