@Test
public void testDeleteContainer() throws Exception {
    String containerName;
    ContainerData containerData;
    Pipeline pipeline;
    String[] delCmd;
    ByteArrayOutputStream testErr;
    int exitCode;
    // ****************************************
    // 1. Test to delete a non-empty container.
    // ****************************************
    // Create an non-empty container
    ContainerWithPipeline container = containerOperationClient.createContainer(xceiverClientManager.getType(), HddsProtos.ReplicationFactor.ONE, containerOwner);
    KeyValueContainerData kvData = KeyValueContainerData.getFromProtoBuf(containerOperationClient.readContainer(container.getContainerInfo().getContainerID(), container.getPipeline()));
    KeyUtils.getDB(kvData, conf).put(Longs.toByteArray(container.getContainerInfo().getContainerID()), "someKey".getBytes());
    Assert.assertTrue(containerExist(container.getContainerInfo().getContainerID()));
    // Gracefully delete a container should fail because it is open.
    delCmd = new String[] { "-container", "-delete", "-c", Long.toString(container.getContainerInfo().getContainerID()) };
    testErr = new ByteArrayOutputStream();
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    exitCode = runCommandAndGetOutput(delCmd, out, testErr);
    assertEquals(EXECUTION_ERROR, exitCode);
    assertTrue(testErr.toString().contains("Deleting an open container is not allowed."));
    Assert.assertTrue(containerExist(container.getContainerInfo().getContainerID()));
    // Close the container
    containerOperationClient.closeContainer(container.getContainerInfo().getContainerID());
    // Gracefully delete a container should fail because it is not empty.
    testErr = new ByteArrayOutputStream();
    int exitCode2 = runCommandAndGetOutput(delCmd, out, testErr);
    assertEquals(EXECUTION_ERROR, exitCode2);
    assertTrue(testErr.toString().contains("Container cannot be deleted because it is not empty."));
    Assert.assertTrue(containerExist(container.getContainerInfo().getContainerID()));
    // Try force delete again.
    delCmd = new String[] { "-container", "-delete", "-c", Long.toString(container.getContainerInfo().getContainerID()), "-f" };
    exitCode = runCommandAndGetOutput(delCmd, out, null);
    assertEquals("Expected success, found:", ResultCode.SUCCESS, exitCode);
    assertFalse(containerExist(container.getContainerInfo().getContainerID()));
    // ****************************************
    // 2. Test to delete an empty container.
    // ****************************************
    // Create an empty container
    ContainerWithPipeline emptyContainer = containerOperationClient.createContainer(xceiverClientManager.getType(), HddsProtos.ReplicationFactor.ONE, containerOwner);
    containerOperationClient.closeContainer(emptyContainer.getContainerInfo().getContainerID());
    Assert.assertTrue(containerExist(emptyContainer.getContainerInfo().getContainerID()));
    // Successfully delete an empty container.
    delCmd = new String[] { "-container", "-delete", "-c", Long.toString(emptyContainer.getContainerInfo().getContainerID()) };
    exitCode = runCommandAndGetOutput(delCmd, out, null);
    assertEquals(ResultCode.SUCCESS, exitCode);
    assertFalse(containerExist(emptyContainer.getContainerInfo().getContainerID()));
    // After the container is deleted,
    // another container can now be recreated.
    ContainerWithPipeline newContainer = containerOperationClient.createContainer(xceiverClientManager.getType(), HddsProtos.ReplicationFactor.ONE, containerOwner);
    Assert.assertTrue(containerExist(newContainer.getContainerInfo().getContainerID()));
    // ****************************************
    // 3. Test to delete a non-exist container.
    // ****************************************
    long nonExistContainerID = ContainerTestHelper.getTestContainerID();
    delCmd = new String[] { "-container", "-delete", "-c", Long.toString(nonExistContainerID) };
    testErr = new ByteArrayOutputStream();
    exitCode = runCommandAndGetOutput(delCmd, out, testErr);
    assertEquals(EXECUTION_ERROR, exitCode);
    assertTrue(testErr.toString().contains("Specified key does not exist."));
}

