/**
 * Send a vaild Ozone Request.
 *
 * @throws IOException
 */
@Test
public void testOzoneRequest() throws IOException {
    SimpleDateFormat format = new SimpleDateFormat("EEE, dd MMM yyyy HH:mm:ss ZZZ", Locale.US);
    CloseableHttpClient client = HttpClients.createDefault();
    String volumeName = getRequestID().toLowerCase(Locale.US);
    try {
        HttpPost httppost = new HttpPost(String.format("http://localhost:%d/%s", port, volumeName));
        httppost.addHeader(Header.OZONE_VERSION_HEADER, Header.OZONE_V1_VERSION_HEADER);
        httppost.addHeader(HttpHeaders.DATE, format.format(new Date(Time.now())));
        httppost.addHeader(HttpHeaders.AUTHORIZATION, Header.OZONE_SIMPLE_AUTHENTICATION_SCHEME + " " + OzoneConsts.OZONE_SIMPLE_HDFS_USER);
        httppost.addHeader(Header.OZONE_USER, OzoneConsts.OZONE_SIMPLE_HDFS_USER);
        HttpResponse response = client.execute(httppost);
        assertEquals(response.toString(), HTTP_CREATED, response.getStatusLine().getStatusCode());
    } finally {
        client.close();
    }
}

